# Generates 200 deterministic boundary/varied test inputs; expected output generated by rules,
# not official-calculator validated. Maintain a separate gold set after manual official checks.
import json
from src.tax_engine import calculate
thresholds=[0,1,249999,250000,250001,300000,500000,500001,700000,700001,1000000,1000001,1200000,1200001,1500000,1500001]
vals=thresholds+[i*25000 for i in range(1,185)]
cases=[{'case_id':i+1,'input':{'salary':v},'expected':calculate({'salary':v})} for i,v in enumerate(vals[:200])]
with open('tests/cases_200.json','w') as f: json.dump(cases,f,indent=2)
styles=['My yearly salary is ₹{}','salary {} rupees yearly','Mera annual package {} hai','I earn Rs {} per annum','income approx {}','My monthly salary is {}','salary is {} but deductions unknown','I make {} INR annually']
with open('tests/plain_language_50.json','w') as f: json.dump([{'text':styles[i%len(styles)].format(vals[i%len(vals)]),'expected':'confirmation_or_clarification'} for i in range(50)],f,indent=2)
if __name__=='__main__': print('Wrote 200 test cases + 50 descriptions')
